2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrect handling of the `SystemCallFilter` and `RestrictAddressFamilies` properties in the D-Bus API, specifically using uninitialized variables and incorrect data structures when setting and appending these properties, which led to improper filtering behavior and potential crashes or unexpected behavior in the system.

        Commit message:
        core: fix D-Bus API

This fixes bugs introduced by cffaed83e87bde81378b2be74192193850d0e03a.

Closes #7129.  

        Patch:

 int bus_exec_context_set_transient_property(
                 Unit *u,
                 ExecContext *c,
                 const char *name,
                 sd_bus_message *message,
                 UnitSetPropertiesMode mode,
                 sd_bus_error *error) {

         const char *soft = NULL;
         int r, ri;

         assert(u);
         assert(c);
         assert(name);
         assert(message);

         if (streq(name, "User")) {
                 const char *uu;

                 r = sd_bus_message_read(message, "s", &uu);
                 if (r < 0)
                         return r;

                 if (!isempty(uu) && !valid_user_group_name_or_id(uu))
                         return sd_bus_error_setf(error, SD_BUS_ERROR_INVALID_ARGS, "Invalid user name: %s", uu);

                 if (mode != UNIT_CHECK) {

                         if (isempty(uu))
                                 c->user = mfree(c->user);
                         else if (free_and_strdup(&c->user, uu) < 0)
                                 return -ENOMEM;

                         unit_write_drop_in_private_format(u, mode, name, "User=%s", uu);
                 }

                 return 1;

         } else if (streq(name, "Group")) {
                 const char *gg;

                 r = sd_bus_message_read(message, "s", &gg);
                 if (r < 0)
                         return r;

                 if (!isempty(gg) && !valid_user_group_name_or_id(gg))
                         return sd_bus_error_setf(error, SD_BUS_ERROR_INVALID_ARGS, "Invalid group name: %s", gg);

                 if (mode != UNIT_CHECK) {

                         if (isempty(gg))
                                 c->group = mfree(c->group);
                         else if (free_and_strdup(&c->group, gg) < 0)
                                 return -ENOMEM;

                         unit_write_drop_in_private_format(u, mode, name, "Group=%s", gg);
                 }

